param([Parameter(Mandatory=$true)][string]$Backup,[string]$TargetDatabase='chahinaz_pos_restore',[switch]$AllowProduction,[switch]$ConfirmRestore)
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$envFile=Join-Path $root '.env.production';if(!(Test-Path $Backup)){throw 'Backup file does not exist.'};$cfg=@{};Get-Content $envFile|Where-Object{$_ -match '^[A-Z0-9_]+='}|ForEach-Object{$k,$v=$_.Split('=',2);$cfg[$k]=$v};if($TargetDatabase-eq$cfg.POS_DB_NAME-and!$AllowProduction){throw 'Production restore is blocked. Restore to a test database first. Use -AllowProduction only during approved disaster recovery.'};if(!$ConfirmRestore-and(Read-Host "Type RESTORE to replace database '$TargetDatabase'")-ne'RESTORE'){throw 'Restore cancelled.'}
docker compose --env-file $envFile -f (Join-Path $root 'compose.production.yaml') exec -T postgres sh -c "PGPASSWORD=`"`$POSTGRES_PASSWORD`" dropdb -U `"`$POSTGRES_USER`" --if-exists '$TargetDatabase' && PGPASSWORD=`"`$POSTGRES_PASSWORD`" createdb -U `"`$POSTGRES_USER`" '$TargetDatabase'";if($LASTEXITCODE-ne 0){throw 'Could not prepare restore database.'}
docker cp $Backup chahinaz-pos-production-postgres:/tmp/chahinaz-restore.dump
docker compose --env-file $envFile -f (Join-Path $root 'compose.production.yaml') exec -T postgres sh -c "PGPASSWORD=`"`$POSTGRES_PASSWORD`" pg_restore -U `"`$POSTGRES_USER`" -d '$TargetDatabase' --clean --if-exists /tmp/chahinaz-restore.dump";$code=$LASTEXITCODE;docker compose --env-file $envFile -f (Join-Path $root 'compose.production.yaml') exec -T postgres rm -f /tmp/chahinaz-restore.dump;if($code-ne 0){throw 'Restore failed.'};Write-Host "Restore completed into $TargetDatabase. Verify it before production recovery." -ForegroundColor Green
